import bisect

def count_in_ranges(points, ranges):
    s = sorted(points)
    out = []
    for lo, hi in ranges:
        if hi < lo:
            out.append(0)
        else:
            out.append(bisect.bisect_right(s, hi) - bisect.bisect_left(s, lo))
    return out
